// Keyboard and touch input share the same normalized movement rules.
$('world').addEventListener('pointerdown',()=>$('world').focus({preventScroll:true}));
window.addEventListener('keydown',event=>{if(document.activeElement!==$('world')||event.isComposing||!canWalk())return;if(movingKeys.has(event.code)){event.preventDefault();held.add(event.code);}else if(event.code==='Space')event.preventDefault();else if(event.code==='KeyE'&&!event.repeat){event.preventDefault();enter();}else if(event.code==='Enter'){event.preventDefault();stop();if(account)$('chatInput').focus({preventScroll:true});else showAuth();}});
window.addEventListener('keyup',event=>{held.delete(event.code);if(!held.size&&movingKeys.has(event.code))sendMovement(true);});window.addEventListener('blur',stop);$('world').addEventListener('blur',stop);document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});
document.querySelectorAll('[data-dir]').forEach(button=>{const code={up:'ArrowUp',down:'ArrowDown',left:'ArrowLeft',right:'ArrowRight'}[button.dataset.dir];button.addEventListener('pointerdown',event=>{event.preventDefault();$('world').focus({preventScroll:true});if(!canWalk())return;button.setPointerCapture(event.pointerId);held.add(code);});for(const type of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(type,()=>{held.delete(code);sendMovement(true);});});
let moveSeq=0,lastSent=0,previousMoving=false;function directions(){let dx=0,dy=0;for(const code of held){const v=movingKeys.get(code);if(v){dx+=v[0];dy+=v[1];}}return {dx:Math.sign(dx),dy:Math.sign(dy)};}
function sendMovement(force=false){if(socket?.readyState!==1)return;const {dx,dy}=directions(),active=!!(dx||dy);if(force||active||previousMoving){socket.send(JSON.stringify({type:'move',seq:++moveSeq,dx,dy}));lastSent=performance.now();previousMoving=active;}}
$('enterButton').onclick=enter;async function enter(){const building=near(position);if(!building){toast('건물 입구 가까이로 와주세요.');return;}if(!account){showAuth();return;}venue=building.id;stop();$('venueTitle').textContent=building.name;$('venueEyebrow').textContent={forge:'ONE MORE TRY',fortune:'TAROT · SAJU · LOVE',casino:'PLAY WITH CHOCO'}[venue];const embed=EMBEDDED[venue];$('venueDialog').classList.toggle('forge-mode',!!embed);open($('venueDialog'));if(embed){const frame=document.createElement('iframe');frame.className='forge-frame';frame.title=embed.title;frame.src=embed.src;$('venueContent').replaceChildren(frame);}else{try{await refresh();if(venue==='fortune'&&fortuneTab==='deck')await loadDeck();renderVenue();}catch(error){$('venueContent').innerHTML='<p class="error">'+h(error.message)+'</p><button data-retry>다시 불러오기</button>';$('venueContent').querySelector('[data-retry]').onclick=()=>refresh().then(renderVenue).catch(e=>toast(e.message));}}}
