function cardMarkup(card){const mark=card.suit?({wands:'✦',cups:'♧',swords:'⚔',pentacles:'✧'})[card.suit]:['☀','✦','☾','❀','♜','✧','♡','♞','∞','☼','✺','⚖','☽','❦','♢','♜','ϟ','★','☾','☀','✺','◎'][card.number];return '<div class="tarot-display"><div class="tarot-card"><span class="card-number">'+h(card.number)+'</span><span class="card-mark" aria-hidden="true">'+mark+'</span><span class="card-label">'+h(card.ko)+'</span></div><div><h3>'+h(card.ko)+'</h3><p class="card-direction">'+(card.reversed?'역방향':'정방향')+(card.day?' · '+h(card.day):'')+'</p><div class="keyword-list">'+(card.reversed?card.rev_kw:card.up_kw).map(k=>'<span class="keyword">'+h(k)+'</span>').join('')+'</div><p class="tarot-meaning">'+h(card.reversed?card.rev:card.up)+'</p><p class="card-advice">'+h(card.advice)+'</p></div></div>';}
